 const selectLabel=source.match(/^(.+) auswählen$/);if(selectLabel){const verbs={en:'Select',tr:'Seç',ru:'Выбрать',pl:'Wybierz',ro:'Selectează'};return verbs[appLanguage]+': '+selectLabel[1]}
